MAP
    NAME "EAFW_MapServer"
    STATUS ON
    SIZE 800 600
    UNITS DD
    DEBUG 2
    EXTENT 21 -12 52 23
    IMAGECOLOR 0 0 0
    IMAGETYPE PNG
    FONTSET "fonts/fonts.txt"
    SYMBOLSET "symbols/symbols.sym"

    WEB
        METADATA
            INCLUDE "config/wms-metadata.map"
        END
    END

    PROJECTION
        "init=epsg:4326"
    END

    OUTPUTFORMAT
        NAME "png"
        DRIVER AGG/PNG
        MIMETYPE "image/png"
        IMAGEMODE RGBA
        EXTENSION "png"
        FORMATOPTION "INTERLACE=OFF"
        TRANSPARENT ON
    END

    INCLUDE "layers/admin-extent-mask.map"
    INCLUDE "layers/daily-hmc-alert.map"
    INCLUDE "layers/flood-hazard.map"
    INCLUDE "layers/flood-extent-return-periods.map"
    INCLUDE "layers/wrf-streamflow.map"
    INCLUDE "layers/wrf-daily-rainfall.map"
    INCLUDE "layers/wrf-extreme-rainfall.map"
    INCLUDE "layers/landscan-population.map"
    INCLUDE "layers/asap-cropland.map"
    INCLUDE "layers/asap-rangeland.map"
END
